import{_ as r,o as n,c as t,ah as s}from"./chunks/framework.Bja9t6Wf.js";const m=JSON.parse(`{"title":"STRENG VERTRAULICH: Protokoll der Übernahme Alsberg-Duisburg (1938)","description":"Ein rekonstruiertes Dokument der 'Arisierung' – Die kühle Bürokratie des Raubes.","frontmatter":{"title":"STRENG VERTRAULICH: Protokoll der Übernahme Alsberg-Duisburg (1938)","description":"Ein rekonstruiertes Dokument der 'Arisierung' – Die kühle Bürokratie des Raubes.","date":"1938-05-01T00:00:00.000Z"},"headers":[],"relativePath":"recherche/der-kaufvertrag-horten-alsberg.md","filePath":"recherche/der-kaufvertrag-horten-alsberg.md"}`),a={name:"recherche/der-kaufvertrag-horten-alsberg.md"};function i(l,e,d,u,o,h){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="streng-vertraulich-protokoll-der-ubernahme" tabindex="-1">STRENG VERTRAULICH: Protokoll der Übernahme <a class="header-anchor" href="#streng-vertraulich-protokoll-der-ubernahme" aria-label="Permalink to &quot;STRENG VERTRAULICH: Protokoll der Übernahme&quot;">​</a></h1><p><strong>Datum:</strong> 01. Mai 1938 <strong>Ort:</strong> Duisburg, Geschäftsräume der Gebrüder Alsberg AG (ehemals) <strong>Anwesende:</strong></p><ul><li>Herr Helmut Horten (Käufer)</li><li>Herr Dr. Alfred Alsberg (Verkäufer, unter Vorbehalt)</li><li>Vertreter der Industrie- und Handelskammer (Beobachter)</li><li>Herr S. (Notar)</li></ul><h2 id="gegenstand-der-verhandlung" tabindex="-1">Gegenstand der Verhandlung <a class="header-anchor" href="#gegenstand-der-verhandlung" aria-label="Permalink to &quot;Gegenstand der Verhandlung&quot;">​</a></h2><p>Die vollständige Übernahme des Warenhauses Alsberg in Duisburg durch die neu gegründete <em>Helmut Horten KG</em>.</p><h2 id="feststellungen" tabindex="-1">Feststellungen <a class="header-anchor" href="#feststellungen" aria-label="Permalink to &quot;Feststellungen&quot;">​</a></h2><ol><li>Der Verkäufer (Dr. Alsberg) erklärt sich bereit, sämtliche Anteile, Warenbestände und Immobilien zum Preis von [GESCHWÄRZT] Reichsmark an den Käufer (Herrn Horten) zu übertragen.</li><li>Der Kaufpreis wird auf ein Sperrkonto bei der Dresdner Bank eingezahlt. Der Zugriff des Verkäufers unterliegt den geltenden Devisenbestimmungen für jüdisches Eigentum.</li><li>Der Name „Alsberg“ ist mit sofortiger Wirkung von der Fassade zu entfernen. Sämtliche Briefbögen, Etiketten und Werbemittel sind zu vernichten oder unkenntlich zu machen.</li></ol><h2 id="anmerkungen-des-kaufers-h-horten" tabindex="-1">Anmerkungen des Käufers (H. Horten) <a class="header-anchor" href="#anmerkungen-des-kaufers-h-horten" aria-label="Permalink to &quot;Anmerkungen des Käufers (H. Horten)&quot;">​</a></h2><p>„Es handelt sich hierbei um eine notwendige Marktbereinigung. Das Warenhaus wird unter neuer, arischer Führung zu einem Vorzeigebetrieb der deutschen Wirtschaft ausgebaut. Sämtliche jüdischen Angestellten sind bis zum 30. Mai 1938 freizustellen. Die Abfindungen werden mit dem Kaufpreis verrechnet.“</p><h2 id="einwand-des-verkaufers-dr-alsberg" tabindex="-1">Einwand des Verkäufers (Dr. Alsberg) <a class="header-anchor" href="#einwand-des-verkaufers-dr-alsberg" aria-label="Permalink to &quot;Einwand des Verkäufers (Dr. Alsberg)&quot;">​</a></h2><p>„Der Kaufpreis entspricht nicht einmal dem Wert der Warenbestände im Keller. Dies ist kein Verkauf, dies ist eine Liquidation meiner Existenz.“</p><h2 id="schlussbestimmung" tabindex="-1">Schlussbestimmung <a class="header-anchor" href="#schlussbestimmung" aria-label="Permalink to &quot;Schlussbestimmung&quot;">​</a></h2><p>Der Vertrag ist rechtsgültig. Einsprüche sind aufgrund der aktuellen Gesetzeslage (Verordnung über den Einsatz jüdischen Vermögens) ausgeschlossen.</p><p><strong>Gezeichnet:</strong><em>Helmut Horten</em><em>(Unterschrift Alfred Alsberg – zittrig)</em></p><hr><p><em>Hintergrund-Info der Redaktion (2026):</em> Dieses Protokoll wurde in den 1950er Jahren während der Restitutionsverhandlungen als „verschollen“ gemeldet. Es tauchte erst Jahrzehnte später in einem privaten Archiv auf. Es belegt die kühle, fast geschäftsmäßige Brutalität, mit der Helmut Horten sein Imperium auf den Trümmern jüdischer Existenzen errichtete.</p>',16)])])}const c=r(a,[["render",i]]);export{m as __pageData,c as default};
